mapper.update:
update async_order_command
set status = 0,
    retry_count = #{retryCount},
    next_retry_time = #{nextRetryTime},
    lease_owner = null,
    lease_until = null,
    last_error = #{lastError}
where command_id = #{commandId}
  and status = 1
  and lease_owner = #{owner}

update async_order_command
set status = 3,
    lease_owner = null,
    lease_until = null,
    last_error = #{lastError},
    dead_letter_time = #{deadLetterTime}
where command_id = #{commandId}
  and status = 1
  and lease_owner = #{owner}
